DO $$ DECLARE v_definition text; BEGIN SELECT pg_get_functiondef('public.aplica_extragere_comanda(text[],jsonb,text,integer)'::regprocedure) INTO v_definition; v_definition:=replace(v_definition, 'SELECT count(*) INTO v_expected FROM public.mesaje WHERE id=ANY(p_mesaje) AND telefon=v_phone AND status IN (''nou'',''asteapta_client'') AND tip_mesaj IS NULL FOR UPDATE;', 'PERFORM id FROM public.mesaje WHERE id=ANY(p_mesaje) FOR UPDATE; SELECT count(*) INTO v_expected FROM public.mesaje WHERE id=ANY(p_mesaje) AND telefon=v_phone AND status IN (''nou'',''asteapta_client'') AND tip_mesaj IS NULL;'); EXECUTE v_definition; END $$;